{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C03", "C12", "C17", "C32", "C21", "C08", "C58"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C12", "C17", "C32", "C21", "C08", "C58"],
  "claims": [
    {
      "claim": "The query is an SGLT2 inhibitor with a bridged dioxabicyclooctane core and the same 4-chloro-3-(4-ethoxybenzyl)phenyl aglycone as dapagliflozin; the closely related tofogliflozin context reports absolute oral bioavailability of about 97.5–98% in humans and 97% in a summary table, all far above the 20% threshold.",
      "card_ids": ["C03", "C12", "C17", "C32"]
    },
    {
      "claim": "A tofogliflozin record reports high bioavailability after a single 20 mg oral dose, and monkey data show 85% F, consistent with high oral bioavailability.",
      "card_ids": ["C08", "C21"]
    },
    {
      "claim": "L4 dapagliflozin oral-solution record shows rapid absorption (Tmax <1 h) and at least 75% systemic absorption within 24 h, supporting the absorption component for the shared aglycone.",
      "card_ids": ["C58"]
    },
    {
      "claim": "L5 dapagliflozin Caco-2 records show good intrinsic permeability and identify dapagliflozin as a weak P-gp substrate (efflux ratio 3.8) but not a significant inhibitor; this is mechanistic efflux context and does not provide affirmative evidence of F <20% for the query.",
      "card_ids": ["C70", "C69", "C64"]
    },
    {
      "claim": "No L5 record directly measures the query molecule; the remaining L5 records concern unrelated molecules and do not bear on the query's oral bioavailability.",
      "card_ids": ["C59", "C60", "C61", "C62", "C63", "C65", "C66", "C67", "C68"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C70", "C69", "C64"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present; the decision relies on structural transfer from tofogliflozin and class/aglycone exposure data.",
    "No query-specific gut-wall efflux or intestinal-metabolism assay is supplied in L5; the relevant L5 records are for dapagliflozin, which shares the aglycone but not the bridged dioxabicyclooctane core.",
    "The tofogliflozin absolute-F records do not explicitly report a fasted condition; fasted-state transfer is inferred, though dapagliflozin L3 records show comparable AUC in fed vs fasted states.",
    "C58 reports systemic absorption of at least 75% for dapagliflozin, not the query itself, and does not directly measure absolute oral bioavailability.",
    "The query physicochemical prior is mixed (high TPSA/HBD), but no affirmative experimental evidence indicates F <20%.",
    "L5 dapagliflozin efflux ratio 3.8 indicates potential P-gp efflux, but its quantitative impact on the query's F is unknown and not directly measured."
  ],
  "decision_summary": "High: tofogliflozin absolute F ~97.5–98% in humans and dapagliflozin same-aglycone absorption ≥75% support F >=20%; L5 adds only mechanistic P-gp efflux context for dapagliflozin with no affirmative low-F evidence for the query."
}

